./novamind-operation python-c "
import novamind_api as nm
# Get help on each function
import inspect
modules = [nm.pricing, nm.analytics, nm.enterprise, nm.infrastructure, nm.market, nm.marketing, nm.research]
for m in modules:
    print(f'=== {m.__name__} ===')
    for name in dir(m):
        if not name.startswith('_'):
            obj = getattr(m, name)
            if callable(obj):
                try:
                    print(f'  {name}{inspect.signature(obj)}')
                except:
                    print(f'  {name}(...)')
    print()
" 2>&1

