        if isinstance(v, dict):
            print(f'{k}:')
            for k2, v2 in v.items():
                if isinstance(v2, dict):
                    print(f'  {k2}: {v2}')
                else:
                    print(f'  {k2}: {v2}')
        elif isinstance(v, list):
            print(f'{k}: {len(v)} items')
            for item in v[:5]:
                print(f'  {item}')
        else:
            print(f'{k}: {v}')
