import novamind_api as nm

# Social posts - check format
posts = nm.analytics.get_social_posts(days=14, limit=50)
print('=== SOCIAL POSTS (last 14 days) ===')
print(type(posts))
if isinstance(posts, list) and len(posts) > 0:
    print(type(posts[0]))
    print(posts[0])
    print()
    for p in posts:
        if isinstance(p, dict):
            print(f\"Day {p.get('day','?')} | {p.get('author','?')} | {p.get('content','')[:140]}\")
        else:
            print(str(p)[:150])
elif isinstance(posts, dict):
    print(posts)
else:
    print(posts)
"

