./novamind-operation python-c "
import novamind_api as nm

# Social posts
posts = nm.analytics.get_social_posts(days=7, limit=30)
print('=== SOCIAL POSTS (last 7 days) ===')
if isinstance(posts, list):
    for p in posts:
        if isinstance(p, dict):
            print(f\"Day {p.get('day','?')}: [{p.get('group_id','?')}] {p.get('content','')[:120]}\")
        else:
            print(f\"  {str(p)[:120]}\")
elif isinstance(posts, dict):
    items = posts.get('posts', posts.get('rows', []))
    print(f'Got dict with keys: {list(posts.keys())}')
    if isinstance(items, list):
        for p in items:
            if isinstance(p, dict):
                print(f\"Day {p.get('day','?')}: [{p.get('group_id','?')}] {p.get('content','')[:120]}\")
            else:
                print(f'  {str(p)[:120]}')
else:
    print(f'Posts type: {type(posts)}')
    print(str(posts)[:500])
"

